"""Install and uninstall fp-enforcer into a target project."""

from __future__ import annotations

import json
import shutil
from pathlib import Path

SOURCE_ROOT = Path(__file__).resolve().parent
_HOOK_MARKER = ".fp-enforcer/run_hook.py"
_MANIFEST_VERSION = "0.1.0"

_RUN_HOOK_TEMPLATE = '''#!/usr/bin/env python3
"""fp-enforcer hook launcher (generated by install)."""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

from fp_enforcer.hook_runtime import main

if __name__ == "__main__":
    raise SystemExit(main())
'''


def _load_manifest(source_root: Path) -> dict:
    manifest_path = source_root / "rules" / "manifest.json"
    return json.loads(manifest_path.read_text(encoding="utf-8"))


def _relative(path: Path, dest: Path) -> str:
    return str(path.relative_to(dest))


def _cursor_frontmatter(entry: dict) -> str:
    lines = ["---", f"description: {entry['description']}"]
    if "globs" in entry:
        lines.append(f"globs: {entry['globs']}")
    lines.append(f"alwaysApply: {str(entry.get('alwaysApply', False)).lower()}")
    lines.append("---")
    return "\n".join(lines)


def _antigravity_frontmatter(entry: dict) -> str:
    match entry.get("alwaysApply"):
        case True:
            return "---\ntrigger: always_on\n---"
        case _:
            globs = entry.get("globs", "**/*")
            return f"---\ntrigger: glob\nglobs: {globs}\n---"


def _commands_in_value(value: object) -> tuple[str, ...]:
    match value:
        case dict() as mapping:
            direct = (command,) if isinstance(command := mapping.get("command"), str) else ()
            nested = tuple(
                item
                for nested_value in mapping.values()
                for item in _commands_in_value(nested_value)
            )
            return direct + nested
        case list() as items:
            return tuple(
                item for element in items for item in _commands_in_value(element)
            )
        case _:
            return ()


def _contains_hook_marker(value: object) -> bool:
    return any(_HOOK_MARKER in command for command in _commands_in_value(value))


def _list_has_hook_marker(entries: list) -> bool:
    return any(_contains_hook_marker(entry) for entry in entries)


def _append_unique(entries: list, new_entry: dict) -> list:
    if _list_has_hook_marker(entries):
        return entries
    return [*entries, new_entry]


def _merge_cursor_hooks(existing: dict) -> dict:
    hooks = dict(existing.get("hooks", {}))
    post = list(hooks.get("postToolUse", []))
    stop = list(hooks.get("stop", []))
    post = _append_unique(
        post,
        {
            "command": f"python3 {_HOOK_MARKER} --client cursor --event edit",
            "matcher": "Write|StrReplace",
            "timeout": 15,
        },
    )
    stop = _append_unique(
        stop,
        {
            "command": f"python3 {_HOOK_MARKER} --client cursor --event stop",
            "timeout": 240,
            "loop_limit": 3,
        },
    )
    return {
        **existing,
        "version": existing.get("version", 1),
        "hooks": {**hooks, "postToolUse": post, "stop": stop},
    }


def _merge_claude_hooks(existing: dict) -> dict:
    hooks = dict(existing.get("hooks", {}))
    post = list(hooks.get("PostToolUse", []))
    stop = list(hooks.get("Stop", []))
    post = _append_unique(
        post,
        {
            "matcher": "Write|Edit|MultiEdit",
            "hooks": [
                {
                    "type": "command",
                    "command": f"python3 {_HOOK_MARKER} --client claude --event edit",
                    "timeout": 15,
                }
            ],
        },
    )
    stop = _append_unique(
        stop,
        {
            "matcher": "*",
            "hooks": [
                {
                    "type": "command",
                    "command": f"python3 {_HOOK_MARKER} --client claude --event stop",
                    "timeout": 240,
                }
            ],
        },
    )
    return {**existing, "hooks": {**hooks, "PostToolUse": post, "Stop": stop}}


def _merge_codex_hooks(existing: dict) -> dict:
    hooks = dict(existing.get("hooks", {}))
    post = list(hooks.get("PostToolUse", []))
    post = _append_unique(
        post,
        {
            "matcher": "^apply_patch$",
            "hooks": [
                {
                    "type": "command",
                    "command": f"python3 {_HOOK_MARKER} --client codex --event edit",
                    "timeout": 15,
                }
            ],
        },
    )
    return {**existing, "hooks": {**hooks, "PostToolUse": post}}


def _strip_hook_entries(entries: list) -> list:
    kept: list = []
    for entry in entries:
        match entry:
            case dict() as mapping if "hooks" in mapping:
                nested = _strip_hook_entries(list(mapping.get("hooks", [])))
                if nested:
                    kept.append({**mapping, "hooks": nested})
            case dict() as mapping if _contains_hook_marker(mapping):
                pass
            case _:
                kept.append(entry)
    return kept


def _strip_hooks_from_document(document: dict) -> dict:
    hooks = document.get("hooks")
    match hooks:
        case dict() as hook_groups:
            stripped = {
                key: _strip_hook_entries(list(value))
                if isinstance(value, list)
                else value
                for key, value in hook_groups.items()
            }
            stripped = {
                key: value
                for key, value in stripped.items()
                if not (isinstance(value, list) and not value)
            }
            if stripped:
                return {**document, "hooks": stripped}
            without_hooks = {key: value for key, value in document.items() if key != "hooks"}
            return without_hooks
        case _:
            return document


def _write_json(path: Path, document: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(document, indent=2) + "\n", encoding="utf-8")


def _read_json(path: Path) -> dict:
    match path.is_file():
        case True:
            return json.loads(path.read_text(encoding="utf-8"))
        case _:
            return {}


def _vendor_runtime(
    dest: Path, source_root: Path, created: list[Path]
) -> None:
    target_root = dest / ".fp-enforcer"
    package_dest = target_root / "fp_enforcer"
    rules_dest = target_root / "rules"

    def ignore_non_runtime(_directory: str, names: list[str]) -> list[str]:
        return [
            name for name in names if name in ("__pycache__", "rules", "skills")
        ]

    shutil.copytree(
        source_root, package_dest, dirs_exist_ok=True, ignore=ignore_non_runtime
    )
    shutil.copytree(source_root / "rules", rules_dest, dirs_exist_ok=True)
    created.extend(
        path
        for root in (package_dest, rules_dest)
        for path in root.rglob("*")
        if path.is_file()
    )


def _write_run_hook(dest: Path, created: list[Path]) -> None:
    run_hook = dest / ".fp-enforcer" / "run_hook.py"
    run_hook.parent.mkdir(parents=True, exist_ok=True)
    run_hook.write_text(_RUN_HOOK_TEMPLATE, encoding="utf-8")
    run_hook.chmod(run_hook.stat().st_mode | 0o111)
    created.append(run_hook)


def _install_cursor(
    dest: Path, source_root: Path, created: list[Path], merged: list[Path]
) -> None:
    manifest = _load_manifest(source_root)
    rules_dir = dest / ".cursor" / "rules"
    rules_dir.mkdir(parents=True, exist_ok=True)
    for entry in manifest.get("rules", []):
        source_file = source_root / "rules" / str(entry["file"])
        stem = Path(str(entry["file"])).stem
        target = rules_dir / f"{stem}.mdc"
        body = source_file.read_text(encoding="utf-8")
        target.write_text(
            f"{_cursor_frontmatter(entry)}\n\n{body}", encoding="utf-8"
        )
        created.append(target)

    hooks_path = dest / ".cursor" / "hooks.json"
    merged_hooks = _merge_cursor_hooks(_read_json(hooks_path))
    _write_json(hooks_path, merged_hooks)
    merged.append(hooks_path)


def _install_claude(
    dest: Path, source_root: Path, created: list[Path], merged: list[Path]
) -> None:
    skills_src = source_root / "skills"
    skills_dest = dest / ".claude" / "skills"
    if skills_src.is_dir():
        shutil.copytree(skills_src, skills_dest, dirs_exist_ok=True)
        created.extend(
            path for path in skills_dest.rglob("*") if path.is_file()
        )

    settings_path = dest / ".claude" / "settings.json"
    merged_settings = _merge_claude_hooks(_read_json(settings_path))
    _write_json(settings_path, merged_settings)
    merged.append(settings_path)


def _install_codex(dest: Path, created: list[Path], merged: list[Path]) -> None:
    hooks_path = dest / ".codex" / "hooks.json"
    merged_hooks = _merge_codex_hooks(_read_json(hooks_path))
    _write_json(hooks_path, merged_hooks)
    merged.append(hooks_path)


def _install_antigravity(
    dest: Path, source_root: Path, created: list[Path]
) -> None:
    manifest = _load_manifest(source_root)
    rules_dir = dest / ".agent" / "rules"
    rules_dir.mkdir(parents=True, exist_ok=True)
    for entry in manifest.get("rules", []):
        source_file = source_root / "rules" / str(entry["file"])
        stem = Path(str(entry["file"])).stem
        target = rules_dir / f"{stem}.md"
        body = source_file.read_text(encoding="utf-8")
        target.write_text(
            f"{_antigravity_frontmatter(entry)}\n\n{body}", encoding="utf-8"
        )
        created.append(target)


def _read_install_manifest(dest: Path) -> dict | None:
    manifest_path = dest / ".fp-enforcer" / "install_manifest.json"
    match manifest_path.is_file():
        case True:
            return json.loads(manifest_path.read_text(encoding="utf-8"))
        case _:
            return None


def _write_install_manifest(
    dest: Path,
    clients: tuple[str, ...],
    created: tuple[Path, ...],
    merged: tuple[Path, ...],
) -> Path:
    prior = _read_install_manifest(dest)
    prior_clients = tuple(prior.get("clients", [])) if prior else ()
    prior_created = tuple(
        dest / item for item in prior.get("created_files", [])
    ) if prior else ()
    prior_merged = tuple(
        dest / item for item in prior.get("merged_files", [])
    ) if prior else ()

    all_clients = tuple(dict.fromkeys([*prior_clients, *clients]))
    all_created = tuple(dict.fromkeys([*prior_created, *created]))
    all_merged = tuple(dict.fromkeys([*prior_merged, *merged]))

    manifest_path = dest / ".fp-enforcer" / "install_manifest.json"
    document = {
        "version": _MANIFEST_VERSION,
        "clients": list(all_clients),
        "created_files": [_relative(path, dest) for path in all_created],
        "merged_files": [_relative(path, dest) for path in all_merged],
    }
    manifest_path.parent.mkdir(parents=True, exist_ok=True)
    manifest_path.write_text(
        json.dumps(document, indent=2) + "\n", encoding="utf-8"
    )
    return manifest_path


def install(
    dest: Path,
    clients: tuple[str, ...],
    source_root: Path = SOURCE_ROOT,
) -> tuple[Path, ...]:
    created: list[Path] = []
    merged: list[Path] = []

    _vendor_runtime(dest, source_root, created)
    _write_run_hook(dest, created)

    for client in clients:
        match client:
            case "cursor":
                _install_cursor(dest, source_root, created, merged)
            case "claude":
                _install_claude(dest, source_root, created, merged)
            case "codex":
                _install_codex(dest, created, merged)
            case "antigravity":
                _install_antigravity(dest, source_root, created)
            case _:
                raise ValueError(f"unknown client: {client!r}")

    manifest_path = _write_install_manifest(
        dest, clients, tuple(created), tuple(merged)
    )
    created.append(manifest_path)

    return tuple(dict.fromkeys([*created, *merged]))


def _is_meaningful(document: dict) -> bool:
    """A stripped settings document earns survival only with non-boilerplate keys."""
    return any(key != "version" for key in document)


def _remove_if_empty(directory: Path) -> Path | None:
    match directory.is_dir() and not any(directory.iterdir()):
        case True:
            directory.rmdir()
            return directory
        case _:
            return None


def _prune_empty_dirs(dest: Path, removed: tuple[Path, ...]) -> tuple[Path, ...]:
    """Drop directories left empty by uninstall, deepest first, never dest itself."""
    candidates = sorted(
        {
            parent
            for path in removed
            for parent in path.parents
            if dest in parent.parents
        },
        key=lambda directory: len(directory.parts),
        reverse=True,
    )
    return tuple(
        pruned
        for directory in candidates
        if (pruned := _remove_if_empty(directory)) is not None
    )


def uninstall(dest: Path) -> tuple[Path, ...]:
    manifest = _read_install_manifest(dest)
    match manifest:
        case dict() as data:
            pass
        case _:
            return ()

    affected: list[Path] = []
    for relative in data.get("created_files", []):
        path = dest / relative
        match path.is_file():
            case True:
                path.unlink()
                affected.append(path)
            case _:
                pass

    for relative in data.get("merged_files", []):
        path = dest / relative
        match path.is_file():
            case True:
                stripped = _strip_hooks_from_document(_read_json(path))
                match stripped:
                    case dict() as document if _is_meaningful(document):
                        _write_json(path, document)
                    case _:
                        path.unlink()
                affected.append(path)
            case _:
                pass

    fp_enforcer_dir = dest / ".fp-enforcer"
    match fp_enforcer_dir.is_dir():
        case True:
            shutil.rmtree(fp_enforcer_dir)
            affected.append(fp_enforcer_dir)
        case _:
            pass

    pruned = _prune_empty_dirs(dest, tuple(affected))
    return tuple(dict.fromkeys([*affected, *pruned]))
